"use client"

import { EventCard } from "./event-card"
import { EventCardFeatured } from "./event-card-featured"
import { EventListItem } from "./event-list-item"
import type { Event } from "@/lib/events-data"

interface EventsGridProps {
  events: Event[]
  onEventClick: (event: Event) => void
  viewMode?: "grid" | "list"
}

export function EventsGrid({ events, onEventClick, viewMode = "grid" }: EventsGridProps) {
  if (events.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center">
        <div className="w-24 h-24 mb-6 rounded-full bg-muted flex items-center justify-center">
          <span className="text-4xl">🔍</span>
        </div>
        <h3 className="text-xl font-semibold text-foreground mb-2">Мероприятия не найдены</h3>
        <p className="text-muted-foreground max-w-md">Попробуйте изменить параметры поиска или сбросить фильтры</p>
      </div>
    )
  }

  if (viewMode === "list") {
    return (
      <div className="flex flex-col gap-4">
        {events.map((event) => (
          <EventListItem key={event.id} event={event} onDetailsClick={onEventClick} />
        ))}
      </div>
    )
  }

  // Bento Grid Layout - первые 2 карточки крупные, остальные стандартные
  const featuredEvents = events.slice(0, 2)
  const regularEvents = events.slice(2)

  return (
    <div className="space-y-4">
      {/* Featured Section - Bento Grid */}
      {featuredEvents.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {featuredEvents.map((event, index) => (
            <EventCardFeatured
              key={event.id}
              event={event}
              onDetailsClick={onEventClick}
              priority={index === 0}
            />
          ))}
        </div>
      )}

      {/* Regular Grid */}
      {regularEvents.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
          {regularEvents.map((event) => (
            <EventCard key={event.id} event={event} onDetailsClick={onEventClick} />
          ))}
        </div>
      )}
    </div>
  )
}
